// Theme 28 press tiles (paper fibre, ink mottle, halftone screens), inlined as data: URIs so the export needs no file reads.
const T = {
  "ink-mottle.png": 'data:image/png;base64,',
  "paper-fibre.png": 'data:image/png;base64,',
  "screen-17.png": 'data:image/png;base64,',
  "screen-24.png": 'data:image/png;base64,',
  "screen-25.png": 'data:image/png;base64,',
  "screen-55.png": 'data:image/png;base64,',
  "screen-ring.png": 'data:image/png;base64,',
};
export const tile = (f) => { if (!T[f]) throw new Error('theme 28: no tile ' + f); return T[f]; };
